// Native Elastic Safetensors reader for Qwen3.8-Flash-Next (qwen4exp, #849).
// Parses config.json ("gguf_kv"), hf_quant_config.json ("atlas_elastic"), and model.safetensors.index.json
// generated by tools/quantize_elastic_qwen4exp.py. Strictly CUDA-free host module.
#pragma once

#include "backends/qwen4exp/qwen4exp_config.h"
#include "core/safetensors.h"
#include "ingine/model_backend.h"

#include <cstdint>
#include <filesystem>
#include <memory>
#include <span>
#include <string>
#include <unordered_map>
#include <vector>

namespace ingine::backends::qwen4exp {

enum class ElasticTensorKind : std::uint8_t {
  F32 = 0,
  Bf16 = 1,
  Fp8 = 2,
  Nvfp4 = 3,
  Atlas3 = 4,
  Atlas2 = 5,
};

struct SafetensorsEntry {
  std::string name;
  std::string dtype;
  std::vector<std::int64_t> shape;
  std::size_t shard_index = 0;
  std::uint64_t data_offset = 0;
  std::uint64_t byte_size = 0;
};

struct ElasticShardInfo {
  std::string filename;
  std::filesystem::path full_path;
  std::uint64_t file_size = 0;
  std::uint64_t data_start = 0;
  std::shared_ptr<ingine::SafetensorsFile> file;
};

class Qwen4ExpElasticSet {
 public:
  static bool is_elastic_dir(const std::filesystem::path& path);
  static Qwen4ExpElasticSet inspect_headers(const std::filesystem::path& dir);

  [[nodiscard]] const Qwen4ExpConfig& config() const noexcept { return config_; }
  [[nodiscard]] const ingine::model::CheckpointIdentity& identity() const noexcept { return identity_; }
  [[nodiscard]] const std::string& profile() const noexcept { return profile_; }
  [[nodiscard]] const std::string& ple_format() const noexcept { return ple_format_; }
  [[nodiscard]] std::uint64_t total_tensor_bytes() const noexcept { return total_tensor_bytes_; }

  [[nodiscard]] const SafetensorsEntry* find_tensor(const std::string& name) const noexcept;
  [[nodiscard]] const SafetensorsEntry& require_tensor(const std::string& name) const;
  [[nodiscard]] ElasticTensorKind layer_kind(const std::string& prefix) const noexcept;

  void read_tensor_bytes(const SafetensorsEntry& entry, std::uint64_t rel_offset, std::span<std::uint8_t> dst) const;
  [[nodiscard]] std::vector<std::uint8_t> read_tensor_raw(const SafetensorsEntry& entry) const;
  [[nodiscard]] std::vector<float> read_tensor_f32(const SafetensorsEntry& entry) const;
  [[nodiscard]] float read_scalar_f32(const SafetensorsEntry& entry) const;

  // O(1) host-side row lookup for token_embd (FP8 or NVFP4) and host-only PLE shards (NVFP4 or Q8_0).
  void read_embed_row_f32(std::uint64_t row_idx, std::span<float> out) const;
  void read_ple_row_f32(std::uint64_t row_idx, std::span<float> out) const;
  [[nodiscard]] bool has_embedded_ple() const noexcept { return ple_num_shards_ > 0; }

 private:
  Qwen4ExpConfig config_;
  ingine::model::CheckpointIdentity identity_;
  std::string profile_;
  std::string ple_format_;
  int ple_num_shards_ = 0;
  std::uint64_t ple_chunk_rows_ = 2000000ull;
  std::uint64_t total_tensor_bytes_ = 0;
  std::vector<ElasticShardInfo> shards_;
  std::unordered_map<std::string, SafetensorsEntry> tensors_;
  std::unordered_map<std::string, ElasticTensorKind> layer_kinds_;
  std::vector<float> ple_chunk_scale2_;
  float embed_scale_ = 1.0f;
  ElasticTensorKind embed_kind_ = ElasticTensorKind::F32;
};

}  // namespace ingine::backends::qwen4exp
